package com.svrp;
import com.svrp.dao.*;import com.svrp.service.RentalService;import com.svrp.util.DatabaseConnection;import java.time.LocalDate;import java.util.*;
public class Main {
 static final Scanner S=new Scanner(System.in); static RentalService R=new RentalService(new VehicleDAO(),new CustomerDAO(),new ReservationDAO(),new PaymentDAO());
 public static void main(String[]a){try{DatabaseConnection.test();com.svrp.util.DbMigrator.migrate();}catch(Exception e){System.out.println("Database connection failed: "+e.getMessage());return;}while(true){System.out.println("\n=== SMART VEHICLE RENTAL PORTAL ===\n1 Customer CLI\n2 Admin CLI\n3 Start Web UI Server\n0 Exit");int c=i("Choose: ");try{if(c==1)customer();else if(c==2)admin();else if(c==3){com.svrp.web.ApiServer.main(new String[0]);}else if(c==0)break;else System.out.println("Invalid choice");}catch(Exception e){System.out.println("ERROR: "+e.getMessage());}}System.out.println("Goodbye.");}
 static void customer()throws Exception{while(true){System.out.println("\nCUSTOMER\n1 Register\n2 Vehicles\n3 Check availability\n4 Reserve\n5 My reservations\n6 Payment\n7 Cancel\n0 Back");int c=i("Choose: ");switch(c){case 1->register();case 2->R.printVehicles();case 3->check();case 4->reserve();case 5->R.printCustomerReservations(i("Customer ID: "));case 6->pay();case 7->R.cancel(i("Reservation ID: "));case 0-> {return;}default->System.out.println("Invalid choice");}}}
 static void register()throws Exception{int id=R.registerCustomer(s("Name: "),s("Email: "),s("Phone: "),s("License: "));System.out.println("Registered customer ID: "+id);}
 static void check()throws Exception{int id=i("Vehicle ID: ");LocalDate a=d("Start (YYYY-MM-DD): "),b=d("End (YYYY-MM-DD): ");System.out.println(R.available(id,a,b)?"AVAILABLE":"NOT AVAILABLE");}
 static void reserve()throws Exception{int id=R.reserve(i("Customer ID: "),i("Vehicle ID: "),d("Start (YYYY-MM-DD): "),d("End (YYYY-MM-DD): "));System.out.println("Reservation confirmed. ID: "+id);}
 static void pay()throws Exception{int id=i("Reservation ID: ");double amount=Double.parseDouble(s("Amount: "));int p=R.pay(id,amount,s("Method (CASH/CARD/UPI/NET_BANKING): "));System.out.println("Payment recorded. ID: "+p);}
 static void admin()throws Exception{while(true){System.out.println("\nADMIN\n1 Vehicles\n2 Add vehicle\n3 Set availability\n4 All reservations\n5 Customers\n0 Back");int c=i("Choose: ");switch(c){case 1->R.printVehicles();case 2->add();case 3->R.setAvailability(i("Vehicle ID: "),Boolean.parseBoolean(s("Available true/false: ")));case 4->R.printAllReservations();case 5->R.printCustomers();case 0->{return;}default->System.out.println("Invalid choice");}}}
 static void add()throws Exception{String t=s("Type CAR/BIKE/ELECTRIC_SCOOTER: ");String make=s("Make: "),model=s("Model: "),plate=s("License plate: ");double rate=Double.parseDouble(s("Daily rate: "));Integer range=null,cc=null;if(t.equalsIgnoreCase("ELECTRIC_SCOOTER"))range=i("Battery range km: ");else cc=i("Engine CC: ");System.out.println("Added vehicle ID: "+R.addVehicle(t,make,model,plate,rate,range,cc));}
 static String s(String p){System.out.print(p);return S.nextLine().trim();}static int i(String p){while(true)try{return Integer.parseInt(s(p));}catch(Exception e){System.out.println("Enter a valid integer.");}}static LocalDate d(String p){while(true)try{return LocalDate.parse(s(p));}catch(Exception e){System.out.println("Use YYYY-MM-DD.");}}
}
